#include <bits/stdc++.h>
using namespace std;

const long long mod = 998244353;

long long fastPower(long long base, long long exp) {
    long long result = 1;
    long long b = base % mod;
    long long e = exp;
    while (e > 0) {
        if (e & 1) {
            result = (result * b) % mod;
        }
        b = (b * b) % mod;
        e >>= 1;
    }
    return result;
}

long long modInverse(long long x) {
    return fastPower(x, mod - 2);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long N, M, L, R;
    string line;
    getline(cin, line);
    istringstream iss(line);
    iss >> N >> M >> L >> R;

    long long totalCount = R - L + 1;
    long long evenCount = totalCount / 2 + ((totalCount % 2 == 0 && L % 2 == 0) ? 1 : 0);
    long long oddCount = totalCount - evenCount;

    long long answer;
    long long totalCells = N * M;
    if (totalCells % 2 == 1) {
        answer = fastPower(evenCount + oddCount, totalCells);
    } else {
        long long sum = (fastPower(evenCount + oddCount, totalCells) + fastPower(evenCount - oddCount, totalCells)) % mod;
        answer = (sum * modInverse(2)) % mod;
    }
    cout << answer << "\n";
    return 0;
}
